def fill_missing_skus(apps, schema_editor):
    """Generate a unique SKU for every product that has a blank one.

    Required because the new unique=True constraint on Product.sku would
    otherwise fail for existing products with an empty SKU.
    """
    Product = apps.get_model("fms", "Product")
    used = set(
        Product.objects.exclude(sku__isnull=True).exclude(sku="")
        .values_list("sku", flat=True)
    )

    for product in Product.objects.filter(sku="").order_by("pk"):
        base = (
            (product.name or "PROD").strip().upper().replace(" ", "-")[:12]
            .replace("--", "-").strip("-") or "PROD"
        )
        candidate = f"{base}-{product.pk:04d}"
        counter = 1
        while candidate in used:
            candidate = f"{base}-{product.pk:04d}-{counter}"
            counter += 1
        product.sku = candidate
        product.save(update_fields=["sku"])
        used.add(candidate)


def sync_existing_variant_stock(apps, schema_editor):
    """Ensure Product.stock matches the sum of its variant stocks."""
    Product = apps.get_model("fms", "Product")
    for product in Product.objects.prefetch_related("variants").all():
        variants = list(product.variants.all())
        if variants:
            total = sum(v.stock for v in variants)
            if product.stock != total:
                product.stock = total
                product.save(update_fields=["stock"])


